// Liquid glass: a clear slab whose rounded rim bends what lies behind it like a lens.
fn fs_surface(s: Surface) -> vec4<f32> {
    // The slab tips toward its rim; there it bends the backdrop inward, hardest at the edge.
    let tilt = s.normal.xy;
    let bend = -tilt * s.params.z * (1.0 + 0.5 * length(tilt));
    // Glass bends blue further than red: a slight fringe where it bends most.
    let red = backdrop(bend * 0.94).r;
    let green = backdrop(bend).g;
    let blue = backdrop(bend * 1.06).b;
    let behind = vec3<f32>(red, green, blue);
    // Fresnel (Schlick): the slab reflects more of the light the more steeply it is seen.
    let facing = clamp(s.normal.z, 0.0, 1.0);
    let fresnel = 0.04 + 0.96 * pow(1.0 - facing, 5.0);
    // The theme's light, mirrored off the curved rim (Blinn-Phong).
    let half_way = normalize(s.light_dir + vec3<f32>(0.0, 0.0, 1.0));
    let specular = pow(max(dot(s.normal, half_way), 0.0), 60.0);
    // A soft light follows the pointer across the glass.
    let reach = s.pointer.xy - s.position;
    let glow = s.pointer.z * exp(-dot(reach, reach) / 16200.0) * 0.16;
    // A hairline where the slab meets its outline.
    let hairline = smoothstep(-1.5, 0.0, s.distance) * 0.22;
    let body = mix(behind, s.fill.rgb, s.params.x);
    let lit = body + s.light.rgb * (fresnel * 0.5 + specular * 0.55 + glow + hairline);
    return vec4<f32>(lit, 1.0);
}

